BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE r uuid; a uuid; b uuid; f uuid; c uuid; v integer; blocked boolean;
BEGIN
 INSERT INTO public.refurb_receptions(reception_number,reception_date,supplier,vat_scheme,supplier_invoice_nr) VALUES('TEST-COMP-'||gen_random_uuid(),current_date,'TEST COMP','margin','TEST ONLY') RETURNING id INTO r;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents,rma_registered) VALUES(r,0,'Battery',10000,true) RETURNING id INTO a;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents,rma_registered) VALUES(r,1,'Refunded',20000,true) RETURNING id INTO f;
 blocked:=false; BEGIN PERFORM public.assign_reception_supplier_rma(r,array[a],NULL,false,false,'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_COMPENSATION_REQUIRED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Empty compensation accepted'; END IF;
 IF EXISTS(SELECT 1 FROM public.supplier_rma_cases WHERE reception_id=r) THEN RAISE EXCEPTION 'Failed prepare left dossier'; END IF;
 c:=public.assign_reception_supplier_rma(r,array[a],NULL,false,true,'test@example.invalid');
 IF NOT EXISTS(SELECT 1 FROM public.refurb_reception_items WHERE id=a AND compensation_cents=10000) THEN RAISE EXCEPTION 'Purchase price not copied'; END IF;
 IF EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE reception_item_id=f) THEN RAISE EXCEPTION 'Refunded item attached'; END IF;
 blocked:=false; BEGIN PERFORM public.assign_reception_supplier_rma(r,array[f],NULL,true,true,'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_REFUNDED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Explicit refunded selection accepted'; END IF;
 blocked:=false; BEGIN UPDATE public.refurb_reception_items SET refurb_status='RMA' WHERE id=f; EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_REFUNDED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Refunded status reopened'; END IF;
 blocked:=false; BEGIN UPDATE public.refurb_reception_items SET compensation_cents=NULL WHERE id=a; EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_COMPENSATION_REQUIRED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Active compensation cleared'; END IF;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,2,'Booked',7000) RETURNING id INTO b;
 blocked:=false; BEGIN PERFORM public.assign_reception_supplier_rma(r,array[b],c,true,false,'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_COMPENSATION_REQUIRED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Booked compensation inferred without consent'; END IF;
 PERFORM public.assign_reception_supplier_rma(r,array[b],c,true,true,'test@example.invalid');
 IF NOT EXISTS(SELECT 1 FROM public.refurb_reception_items WHERE id=b AND refurb_status='Booked' AND price_cents=7000 AND compensation_cents=7000) THEN RAISE EXCEPTION 'Booked compensation or accounting failed'; END IF;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,3,'Booked',NULL) RETURNING id INTO b;
 blocked:=false; BEGIN UPDATE public.refurb_reception_items SET compensation_cents=1,rma_registered=true WHERE id=b; EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Null-price booked guard bypass'; END IF;
 blocked:=false; BEGIN PERFORM public.assign_reception_supplier_rma(r,array[b],c,true,true,'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_PRICE_MISSING' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Missing purchase price invented'; END IF;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,4,'RMA',0) RETURNING id INTO b;
 PERFORM public.assign_reception_supplier_rma(r,array[b],c,false,false,'test@example.invalid');
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE reception_item_id=b AND expected_cents=0) THEN RAISE EXCEPTION 'Explicit zero not accepted'; END IF;
END $$;
ROLLBACK;
SELECT 'PASS: mandatory compensation, explicit purchase-price consent, refunded exclusion and terminal status, booked accounting preservation, missing-price guard and zero value; fixtures rolled back' as verification;
